/* ---- client, asynchronous (tools/genidl.py) --------------------------- */

/* net_iface without waiting: the request, with the caller's txid (not 0).
 * The reply comes on ch: idl_reply_read, then net_iface_result. */
static inline status_t net_iface_send(handle_t ch, uint32_t idl_txid)
{
    struct net_iface_req idl_q;
    if (!idl_txid)
        return ERR_INVALID_ARGS;
    idl_q.txid = idl_txid;
    idl_q.ordinal = NET_IFACE;
    return drv_channel_write(ch, &idl_q, sizeof(idl_q), NULL, 0);
}

/* The status and results of a reply to net_iface_send (read with
 * idl_reply_read). The reply's handles are taken in every case: moved to
 * the results, or closed (on a failure, or for a NULL result). */
static inline status_t net_iface_result(const void *idl_rep, struct idl_msg *idl_m, uint32_t *out_address, uint32_t *out_mask, uint32_t *out_gateway, uint32_t *out_dns1, uint32_t *out_dns2, uint8_t out_mac[6], uint8_t *out_device, uint8_t *out_link, uint16_t *out_vlan, uint32_t *out_speed, uint32_t *out_version)
{
    const struct net_iface_rep *idl_r = (const struct net_iface_rep *)idl_rep;
    status_t idl_st = idl_rep_status(idl_rep, idl_m->n, sizeof(*idl_r));
    if (idl_st == OK && idl_m->nh != 0)
        idl_st = ERR_INTERNAL;
    if (idl_st != OK) {
        idl_msg_drop(idl_m);
        return idl_st;
    }
    idl_m->nh = 0;
    if (out_address)
        *out_address = idl_r->address;
    if (out_mask)
        *out_mask = idl_r->mask;
    if (out_gateway)
        *out_gateway = idl_r->gateway;
    if (out_dns1)
        *out_dns1 = idl_r->dns1;
    if (out_dns2)
        *out_dns2 = idl_r->dns2;
    for (uint32_t idl_i = 0; out_mac && idl_i < 6; idl_i++)
        out_mac[idl_i] = idl_r->mac[idl_i];
    if (out_device)
        *out_device = idl_r->device;
    if (out_link)
        *out_link = idl_r->link;
    if (out_vlan)
        *out_vlan = idl_r->vlan;
    if (out_speed)
        *out_speed = idl_r->speed;
    if (out_version)
        *out_version = idl_r->version;
    return OK;
}

/* net_wait_change without waiting: the request, with the caller's txid (not 0).
 * The reply comes on ch: idl_reply_read, then net_wait_change_result. */
